<?php declare(strict_types=1);require_once dirname(__DIR__,2).'/security.php';$editing=!empty($spec['id']);$h=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$groups=['Identity'=>['program_code'=>'Program code','qualification_level'=>'Qualification level','department_name'=>'Department','college_name'=>'College','institution_name'=>'Institution','specification_version'=>'Version','academic_year'=>'Academic year','previous_version_file'=>'Previous version reference'],'Location and outcomes'=>['main_location'=>'Main location','branches'=>'Branches','partnerships'=>'Partnerships','qualified_jobs'=>'Qualified jobs','occupational_sectors'=>'Occupational sectors'],'Program design'=>['program_mission'=>'Program mission','program_goals'=>'Program goals','graduate_attributes'=>'Graduate attributes','admission_requirements'=>'Admission requirements','graduation_requirements'=>'Graduation requirements'],'Student support'=>['guidance_orientation'=>'Guidance and orientation','counseling_services'=>'Counseling services','special_support'=>'Special support'],'Teaching and resources'=>['teaching_learning_strategy'=>'Teaching and learning strategy','assessment_strategy'=>'Assessment strategy','learning_resources'=>'Learning resources','facilities_equipment'=>'Facilities and equipment','healthy_safe_environment'=>'Healthy and safe environment'],'Quality assurance'=>['quality_assurance_arrangements'=>'Quality assurance arrangements','quality_assurance_system'=>'Quality assurance system','quality_manual_reference'=>'Quality manual reference','quality_courses_other_departments'=>'Courses offered to other departments','consistency_between_sections'=>'Consistency between sections','plo_assessment_plan'=>'PLO assessment plan','plo_assessment_plan_reference'=>'PLO assessment plan reference'],'Approval'=>['approval_council_committee'=>'Council or committee','approval_reference_no'=>'Approval reference','approval_date_text'=>'Approval date text','notes'=>'Notes']];$long=array_flip(['main_location','branches','partnerships','qualified_jobs','occupational_sectors','program_mission','program_goals','graduate_attributes','admission_requirements','graduation_requirements','guidance_orientation','counseling_services','special_support','teaching_learning_strategy','assessment_strategy','learning_resources','facilities_equipment','healthy_safe_environment','quality_assurance_arrangements','quality_assurance_system','quality_courses_other_departments','consistency_between_sections','plo_assessment_plan','notes']);?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$editing?'Edit':'Create'?> program specification</title><link rel="stylesheet" href="/assets/style.css"><style>main{max-width:980px;margin:auto;padding:1rem}fieldset{margin:1rem 0;padding:1rem;border:1px solid #bbb}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}.field label{display:block;font-weight:700}.field input,.field select,.field textarea{width:100%;max-width:100%;padding:.55rem;box-sizing:border-box}textarea{min-height:7rem}button{min-height:44px}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style></head><body><main id="main-content"><h1><?=$editing?'Edit':'Create'?> program specification</h1><?php if($errors):?><div role="alert"><h2>Please correct the following</h2><ul><?php foreach($errors as $error):?><li><?=$h($error)?></li><?php endforeach;?></ul></div><?php endif;?><form method="post"><?=csrfField()?><fieldset><legend>Core information</legend><div class="grid"><div class="field"><label for="study_plan_id">Study plan</label><select id="study_plan_id" name="study_plan_id"><option value="">Not linked</option><?php foreach($studyPlans as $plan):?><option value="<?=(int)$plan['id']?>" <?=((int)($spec['study_plan_id']??0)===(int)$plan['id'])?'selected':''?>><?=$h($plan['plan_title'].' — '.$plan['program_name'])?></option><?php endforeach;?></select></div><div class="field"><label for="specification_title">Specification title</label><input id="specification_title" name="specification_title" required maxlength="255" value="<?=$h($spec['specification_title']??'')?>"></div><div class="field"><label for="program_name">Program name</label><input id="program_name" name="program_name" required maxlength="255" value="<?=$h($spec['program_name']??'')?>"></div><div class="field"><label for="specification_type">Specification type</label><select id="specification_type" name="specification_type"><?php foreach(['New','Updated'] as $value):?><option <?=($spec['specification_type']??'Updated')===$value?'selected':''?>><?=$h($value)?></option><?php endforeach;?></select></div><div class="field"><label for="total_credit_hours">Total credit hours</label><input id="total_credit_hours" name="total_credit_hours" type="number" min="0" max="1000" value="<?=$h($spec['total_credit_hours']??'')?>"></div><div class="field"><label for="last_review_date">Last review date</label><input id="last_review_date" name="last_review_date" type="date" value="<?=$h($spec['last_review_date']??'')?>"></div><div class="field"><label for="approval_date">Approval date</label><input id="approval_date" name="approval_date" type="date" value="<?=$h($spec['approval_date']??'')?>"></div><div class="field"><label for="approval_status">Approval status</label><select id="approval_status" name="approval_status"><?php foreach(['Draft','Under Review','Approved','Archived'] as $value):?><option <?=($spec['approval_status']??'Draft')===$value?'selected':''?>><?=$h($value)?></option><?php endforeach;?></select></div></div></fieldset><?php foreach($groups as $legend=>$fields):?><fieldset><legend><?=$h($legend)?></legend><div class="grid"><?php foreach($fields as $name=>$label):?><div class="field"><label for="<?=$h($name)?>"><?=$h($label)?></label><?php if(isset($long[$name])):?><textarea id="<?=$h($name)?>" name="<?=$h($name)?>"><?=$h($spec[$name]??'')?></textarea><?php else:?><input id="<?=$h($name)?>" name="<?=$h($name)?>" maxlength="500" value="<?=$h($spec[$name]??'')?>"><?php endif;?></div><?php endforeach;?></div></fieldset><?php endforeach;?><button type="submit">Save program specification</button> <a href="/program-specifications">Cancel</a></form></main></body></html>
